const aliases = { "React.js": "React", "Express.js": "Express", "SwiftUI": "Swift" };
const conceptIcons = { "SQL": Database, "SwiftData": Database, "CloudKit": Cloud, "MVVM": Layers, "Swift Charts": ChartNoAxesCombined, "VisionKit": ScanLine, "Vision": ScanLine, "Tekton": Workflow, "Behave": TestTube2, "REST API": Network, "Boston Dynamics API": Bot, "NASA POWER API": Cloud, "Data Visualization": ChartNoAxesCombined };

export function TechBadge({ name }) {
    const { t } = useLanguage();
    const source = brandIcons[aliases[name] || name];
    const Icon = conceptIcons[name] || Code2;
    return <span className="tech-badge">{source ? <img src={source} alt="" width="18" height="18" className="tech-icon" loading="lazy" /> : <Icon size={16} aria-hidden="true" />}<span>{t(name)}</span></span>;
}

const skills = [
    { category: "Languages", icon: Code2, items: ["Python", "Java", "C", "C++", "JavaScript", "TypeScript", "Swift", "SQL", "PHP", "HTML", "CSS"] },
    { category: "Frameworks", icon: Layers, items: ["React", "Node.js", "Express", "Flask", "Flutter", "SwiftUI"] },
    { category: "Databases", icon: Database, items: ["PostgreSQL", "MongoDB", "SwiftData", "CloudKit"] },
    { category: "DevOps & Tools", icon: Cloud, items: ["Docker", "Kubernetes", "Tekton", "GitHub Actions", "Git", "REST API"] },
    { category: "Concepts", icon: Brain, items: ["Frontend", "Backend", "Full-stack", "API", "Object-Oriented Programming", "Agile Methodology"] },
];

export default function Skills() {
    const { t } = useLanguage();
    return <section id="skills" className="section section-tinted">
        <div className="shell">
            <div className="section-heading"><div><p className="eyebrow">{t("05 / THE TOOLKIT")}</p><h2>{t("Technical Skills")}</h2></div><p>{t("The tools behind the work.")}</p></div>
            <div className="skills-grid">{skills.map(skill => { const {category, icon: Icon, items} = skill; return <article className="skill-card" key={category}>
                <h3><Icon size={20} aria-hidden="true" />{t(category)}</h3>
                <div className="tech-list">{items.map(item => <TechBadge key={item} name={item} />)}</div>
            </article>; })}</div>
        </div>
    </section>;
}
